{
  "candidates": [
    {
      "claimType": "role",
      "statement": "本人是父亲慢性病患者（高血压/糖尿病）的主要照护协调人，负责药物补给与复查管理。",
      "supportingRefs": [
        "o1",
        "o2",
        "o3",
        "o4"
      ],
      "alternativeExplanations": [
        "本人仅是代买药或临时帮忙，并非长期固定的主要责任人",
        "「爸的药」可能指其他男性亲属（如祖父、叔伯），而非直系父亲"
      ],
      "verificationPlan": [
        {
          "op": "retrieveRelated",
          "question": "查询近4个月是否有其他家庭成员（配偶/兄弟姐妹）的陪诊或购药记录，以评估责任分担情况"
        },
        {
          "op": "checkCoverage",
          "question": "确认「爸」在家庭关系图谱中的具体指向（是否确为亲生父亲及共同居住状态）"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现高频次的家庭共担记录，则角色从「主要照护者」降级为「协助者」；若指向非父亲亲属，则需调整家庭结构理解。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "recurringBehavior",
      "statement": "本人在工作日上午存在因陪同家人就医而请假的行为模式。",
      "supportingRefs": [
        "o2",
        "o3"
      ],
      "alternativeExplanations": [
        "这3次请假是偶发性的紧急事件，尚未形成规律性行为模式",
        "请假事由虽写『家人医院』，但实际可能是处理个人事务或其他非陪护类行政流程"
      ],
      "verificationPlan": [
        {
          "op": "comparePeriods",
          "question": "拉长观察窗口至6-12个月，检查此类「上午+请假+医院关联」的事件频率是否持续存在"
        },
        {
          "op": "alignEvents",
          "question": "比对请假时间与陪诊挂号时间的重合度，确认请假是否直接用于陪护"
        }
      ],
      "whatWouldChangeTheAnswer": "若后续月份无类似记录，则该行为仅为孤立事件而非稳定模式；若时间不重合，则因果关系存疑。",
      "evidenceGrade": "线索",
      "action": "observe"
    }
  ]
}
